int def scoreDebtRatio(double:monthlyIncome, double:monthlyDebt) {
    if (monthlyIncome <= 0.0) {
        return 0;
    }
    double ratio = monthlyDebt / monthlyIncome;
    if (ratio <= 0.2) {
        return 25;
    } else if (ratio <= 0.4) {
        return 20;
    } else if (ratio <= 0.5) {
        return 15;
    } else if (ratio <= 0.6) {
        return 8;
    } else {
        return 0;
    }
}


int def scoreOverdue(int:overdueCount, int:maxOverdueDays) {
    if (overdueCount == 0) {
        return 30;
    } else if (overdueCount <= 2 && maxOverdueDays <= 30) {
        return 20;
    } else if (overdueCount <= 4 && maxOverdueDays <= 60) {
        return 10;
    } else if (maxOverdueDays <= 90) {
        return 5;
    } else {
        return 0;
    }
}


int def scoreEmployment(int:employedMonths, str:companyType) {
    int score = 0;
    if (employedMonths >= 36) {
        score = 10;
    } else if (employedMonths >= 12) {
        score = 7;
    } else if (employedMonths >= 6) {
        score = 4;
    }
    if (companyType == "SOE" || companyType == "LISTED") {
        score = score + 5;
    } else if (companyType == "FOREIGN") {
        score = score + 4;
    } else if (companyType == "PRIVATE") {
        score = score + 2;
    }
    return score;
}


int def scoreCreditQuery(int:queryCount3M) {
    if (queryCount3M <= 2) {
        return 10;
    } else if (queryCount3M <= 5) {
        return 5;
    } else if (queryCount3M <= 8) {
        return 0;
    } else {
        return -5;
    }
}


int def scoreCollateral(str:collateralType, double:collateralValue, double:loanAmount) {
    if (loanAmount <= 0.0) {
        return 0;
    }
    if (collateralType == "HOUSE") {
        double cover = collateralValue / loanAmount;
        if (cover >= 1.5) {
            return 20;
        } else if (cover >= 1.0) {
            return 15;
        } else {
            return 8;
        }
    } else if (collateralType == "VEHICLE") {
        double cover = collateralValue / loanAmount;
        if (cover >= 1.5) {
            return 12;
        } else if (cover >= 1.0) {
            return 8;
        } else {
            return 4;
        }
    } else {
        return 0;
    }
}


str def riskLevel(int:totalScore) {
    if (totalScore >= 85) {
        return "A";
    } else if (totalScore >= 70) {
        return "B";
    } else if (totalScore >= 55) {
        return "C";
    } else {
        return "D";
    }
}


str def admit(int:totalScore, boolean:hasJudicialRecord) {
    if (hasJudicialRecord) {
        return "REJECT";
    } else if (totalScore >= 70) {
        return "PASS";
    } else if (totalScore >= 55) {
        return "MANUAL_REVIEW";
    } else {
        return "REJECT";
    }
}


double def suggestLimit(double:monthlyIncome, int:totalScore) {
    double multiplier = 0.0;
    if (totalScore >= 90) {
        multiplier = 30.0;
    } else if (totalScore >= 80) {
        multiplier = 24.0;
    } else if (totalScore >= 70) {
        multiplier = 18.0;
    } else if (totalScore >= 55) {
        multiplier = 12.0;
    } else {
        multiplier = 0.0;
    }
    return monthlyIncome * multiplier;
}


double def interestRate(str:riskLevel) {
    if (riskLevel == "A") {
        return 0.0385;
    } else if (riskLevel == "B") {
        return 0.0495;
    } else if (riskLevel == "C") {
        return 0.0680;
    } else {
        return 0.0;
    }
}


boolean def needManualReview(int:totalScore, int:queryCount3M) {
    if (totalScore >= 55 && totalScore < 70) {
        return true;
    } else if (queryCount3M > 8) {
        return true;
    } else {
        return false;
    }
}
